// 只引用了 data.length，但是整个 data 都会被放到闭包中，长期持有将造成内存泄露
// 应当将 length 的声明放在外面，只引用 length 就行
function outer() {
  const data = new Array(100000).fill(0)
  // const length = data.length;
  return function inner() {
    const length = data.length;
    console.log(length);
  };
}

const closure = outer();
console.dir(closure);

// 动态引用了数据，无法进行优化，这个时候会将所有的词法环境的所有变量都放入闭包
function outer() {
  const data = new Array(100000).fill(0)
  const length = data.length;
  return function inner() {
    console.log(eval("console.log(length)"));
  };
}

const closure = outer();
console.dir(closure);
